KG42.register("rules-4683374557f4948f4011e621",{"id":"36-dsm_mechanism_design::v141-c-R003","paper":"36-dsm_mechanism_design","record":{"rule_id":"v141-c-R003","mechanism_id":"v141-a-M01","name":"Market payment","process_stage":"settlement","market_meaning":"Submission of each user's feasible consumption-demand information is linked to the energy provider's determination, in return, of that user's VCG electricity bill. Scope: VCG exchange of users' consumption-demand declarations for individualized electricity-bill determination. The full-system and user-excluded social-welfare allocation outcomes supply the other-user welfare evaluations used to calculate each user's Clarke-tax payment. Scope: Individual Clarke-tax payments calculated using full-system and user-excluded VCG allocations. Condition: The function h_n is chosen as the Clarke tax in (23), yielding payment rule (24). Users' payments to the grid are nonnegative, the property termed nonnegative transfer. Scope: Users' payments to the grid in the consumer-only VCG formulation (21), (24). Condition: Properties 1–4 and Assumptions 1–3 hold. Each user's VCG payment is no greater than the sum over time slots of its VCG-allocated consumption multiplied by the corresponding market-clearing price for problem (10). Scope: Per-user VCG payment bound for mechanism (21), (24), evaluated at the allocation for true demand information. Condition: Properties 1–4 and Assumptions 1–3 hold.","independence_rationale":"Relations governed by the approved function settlement.payment under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand","clearing.social_welfare","settlement.payment"],"E":[{"edge_id":"v141-c-R003-E001","source":"bidding.demand","target":"settlement.payment","type":"links","constraint_ids":["v141-c-R003-C001"],"evidence_ids":["v141-b-g01-E02","v141-b-g01-E29"]},{"edge_id":"v141-c-R003-E002","source":"clearing.social_welfare","target":"settlement.payment","type":"links","constraint_ids":["v141-c-R003-C002"],"evidence_ids":["v141-b-g01-E19","v141-b-g02-e017","v141-b-g02-e021","v141-b-g02-e022"]}],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Individual Clarke-tax payments calculated using full-system and user-excluded VCG allocations. | Per-user VCG payment bound for mechanism (21), (24), evaluated at the allocation for true demand information. | Users' payments to the grid in the consumer-only VCG formulation (21), (24). | VCG exchange of users' consumption-demand declarations for individualized electricity-bill determination.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E02","v141-b-g01-E19","v141-b-g01-E29","v141-b-g02-e017","v141-b-g02-e021","v141-b-g02-e022","v141-b-g02-e023","v141-b-g02-e024"]},"x":[{"variable_id":"v141-c-R003-x-t-n","symbol":"t_n","meaning":"VCG electricity payment (bill) of user n, determined by the payment rule from declared demand information and VCG allocations.","kind":"operational","domain":"monetary amount in dollars","unit":"dollars","indices":["n"],"evidence_ids":["v141-b-g02-e015","v141-b-g02-e022","v141-b-g02-e023","v141-b-g02-e024"]},{"variable_id":"v141-c-R003-x-xnk","symbol":"x_n^k","meaning":"Power consumption allocated to user n in time slot k by the VCG allocation rule under declared demand information; the payment formula uses x_n^k(\\hat{\\mathbf I}) and x_n^k(\\hat{\\mathbf I}_{-n}).","kind":"operational","domain":"component of a vector in \\hat{\\mathcal X}_n (declared feasible power-consumption set)","unit":"kW","indices":["n","k"],"evidence_ids":["v141-b-g01-E29","v141-b-g02-e017","v141-b-g02-e022"]}],"theta":[{"parameter_id":"v141-c-R003-theta-Ihat","symbol":"\\hat{\\mathbf I}","meaning":"Vector of declared demand information, comprising declared utility parameters, feasible-set bounds, and minimum energy requirements.","value":{"kind":"symbolic","number_value":null,"text_value":"declared demand-information vector"},"unit":null,"indices":[],"evidence_ids":["v141-b-g01-E29","v141-b-g02-e013","v141-b-g02-e014","v141-b-g02-e017"]},{"parameter_id":"v141-c-R003-theta-Ihat-minus-n","symbol":"\\hat{\\mathbf I}_{-n}","meaning":"Declared demand information of all users except user n, used as the argument of the Clarke tax h_n.","value":{"kind":"symbolic","number_value":null,"text_value":"declared demand-information vector excluding user n"},"unit":null,"indices":["n"],"evidence_ids":["v141-b-g02-e016","v141-b-g02-e021","v141-b-g02-e022"]},{"parameter_id":"v141-c-R003-theta-I","symbol":"\\mathbf I","meaning":"Vector of true demand information of all users, used in the VCG allocation and in Theorem 3's payment bound.","value":{"kind":"symbolic","number_value":null,"text_value":"true demand-information vector"},"unit":null,"indices":[],"evidence_ids":["v141-b-g01-E29","v141-b-g02-e014","v141-b-g02-e024"]},{"parameter_id":"v141-c-R003-theta-lambda-star","symbol":"\\lambda_k^*","meaning":"Market-clearing price in time slot k for problem (10).","value":{"kind":"symbolic","number_value":null,"text_value":"market-clearing price"},"unit":"dollars per kW","indices":["k"],"evidence_ids":["v141-b-g02-e024","v141-b-g03-e12-eq27"]}],"phi":[{"constraint_id":"v141-c-R003-C001","kind":"procedural","role":"core","statement":"Submission of each user's feasible consumption-demand information is linked to the energy provider's determination, in return, of that user's VCG electricity bill. Scope: VCG exchange of users' consumption-demand declarations for individualized electricity-bill determination.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand","settlement.payment"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E02","v141-b-g01-E29","v141-b-g03-e01-vcg-declaration"]},{"constraint_id":"v141-c-R003-C002","kind":"mathematical","role":"core","statement":"The full-system and user-excluded social-welfare allocation outcomes supply the other-user welfare evaluations used to calculate each user's Clarke-tax payment. Scope: Individual Clarke-tax payments calculated using full-system and user-excluded VCG allocations. Condition: The function h_n is chosen as the Clarke tax in (23), yielding payment rule (24).","expression":"h_n(\\hat{\\mathbf I}_{-n}) = \\sum_{m\\in\\mathcal N_{-n}} \\hat U_m\\left(\\sum_{k\\in\\mathcal K} x_m^k(\\hat{\\mathbf I}_{-n})\\right) - \\sum_{k\\in\\mathcal K} C_k\\left(\\sum_{m\\in\\mathcal N_{-n}} x_m^k(\\hat{\\mathbf I}_{-n})\\right); \\quad t_n(\\hat{\\mathbf I}) = -\\left(\\sum_{m\\in\\mathcal N_{-n}} \\hat U_m\\left(\\sum_{k\\in\\mathcal K} x_m^k(\\hat{\\mathbf I})\\right) - \\sum_{k\\in\\mathcal K} C_k\\left(\\sum_{m\\in\\mathcal N} x_m^k(\\hat{\\mathbf I})\\right)\\right) + \\left(\\sum_{m\\in\\mathcal N_{-n}} \\hat U_m\\left(\\sum_{k\\in\\mathcal K} x_m^k(\\hat{\\mathbf I}_{-n})\\right) - \\sum_{k\\in\\mathcal K} C_k\\left(\\sum_{m\\in\\mathcal N_{-n}} x_m^k(\\hat{\\mathbf I}_{-n})\\right)\\right).","formalization_origin":"source","template_id":null,"members":["clearing.social_welfare","settlement.payment"],"variable_refs":["v141-c-R003-x-t-n","v141-c-R003-x-xnk"],"parameter_refs":["v141-c-R003-theta-Ihat","v141-c-R003-theta-Ihat-minus-n"],"evidence_ids":["v141-b-g01-E19","v141-b-g02-e017","v141-b-g02-e021","v141-b-g02-e022","v141-b-g02-e016","v141-b-g02-e018"]},{"constraint_id":"v141-c-R003-C003","kind":"mathematical","role":"core","statement":"Users' payments to the grid are nonnegative, the property termed nonnegative transfer. Scope: Users' payments to the grid in the consumer-only VCG formulation (21), (24). Condition: Properties 1–4 and Assumptions 1–3 hold.","expression":"t_n \\ge 0","formalization_origin":"source","template_id":null,"members":["settlement.payment"],"variable_refs":["v141-c-R003-x-t-n"],"parameter_refs":[],"evidence_ids":["v141-b-g02-e023","v141-b-g01-E07","v141-b-g02-e030"]},{"constraint_id":"v141-c-R003-C004","kind":"mathematical","role":"core","statement":"Each user's VCG payment is no greater than the sum over time slots of its VCG-allocated consumption multiplied by the corresponding market-clearing price for problem (10). Scope: Per-user VCG payment bound for mechanism (21), (24), evaluated at the allocation for true demand information. Condition: Properties 1–4 and Assumptions 1–3 hold.","expression":"t_n \\le \\sum_{k\\in\\mathcal K} \\lambda_k^* x_n^k(\\mathbf I)","formalization_origin":"source","template_id":null,"members":["settlement.payment"],"variable_refs":["v141-c-R003-x-t-n","v141-c-R003-x-xnk"],"parameter_refs":["v141-c-R003-theta-lambda-star","v141-c-R003-theta-I"],"evidence_ids":["v141-b-g02-e024","v141-b-g03-e12-eq27","v141-b-g02-e017","v141-b-g02-e022"]}],"pi":[{"evidence_id":"v141-b-g01-E02","location":{"location_id":"src-0fb1d9d41e-p01-c1r2__v141-a-M01-bidding","page":1,"printed_page":"1170","section":"Abstract","anchor_text":"Abstract—In the future smart grid, both users and power com- ne panies can potentially beneﬁt from t","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"Our design requires that each user provides some information about its energy demand. In return, the energy provider will determine each user’s electricity bill payment."},{"evidence_id":"v141-b-g01-E19","location":{"location_id":"src-0fb1d9d41e-p04-c2r3__v141-a-M01-clearing","page":4,"printed_page":"1173","section":"II-D Problem Formulation and Efficient Allocations","anchor_text":"se terized as the solution of the following problem: er. eir me (10) on ar- where is the vector of p","equation_id":"(10)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"In this section, we consider the problem of power consumption level selection. From a social fairness point of view, it is desirable to utilize the available generated power provided by the energy provider in such a way that the sum of the utility functions of all users is maximized and the cost imposed on the energy provider is minimized. If centralized control is feasible and we can collect all information about the users’ utility functions, an efficient energy consumption schedule can be characterized as the solution of the following problem: \\underset{\\mathbf{x}_n \\in \\mathcal{X}_n,\\, n \\in \\mathcal{N}}{\\text{maximize}} \\sum_{n\\in\\mathcal{N}} U_n\\left(\\sum_{k\\in\\mathcal{K}} x_n^k\\right) - \\sum_{k\\in\\mathcal{K}} C_k\\left(\\sum_{n\\in\\mathcal{N}} x_n^k\\right), \\tag{10} where \\mathbf{x}_n is the vector of power consumptions of user n, U_n(\\cdot) is as in (7), and C_k(\\cdot) is defined in (9). The objective function in problem (10) is the sum of all utility functions minus the total energy cost in the system."},{"evidence_id":"v141-b-g01-E29","location":{"location_id":"src-0fb1d9d41e-p05-c2r4__v141-a-M01-bidding","page":5,"printed_page":"1174","section":"III-A VCG Mechanism","anchor_text":"gy A. VCG Mechanism me In the VCG class of mechanisms, each user is asked to specify ot. its feasibl","equation_id":"(15)-(16)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"In the VCG class of mechanisms, each user is asked to specify its feasible set of power consumption and its utility function, which in case of the utility functions in (7) reduces to revealing a utility parameter \\omega_n. For each user n, we use U_n(\\sum_{k\\in\\mathcal{K}} x_n^k;\\omega_n) and \\hat{U}_n(\\sum_{k\\in\\mathcal{K}} x_n^k;\\hat{\\omega}_n) \\triangleq U(\\sum_{k\\in\\mathcal{K}} x_n^k;\\hat{\\omega}_n) to denote the true and declared utility function and \\mathcal{X}_n and \\hat{\\mathcal{X}}_n to denote the true and declared feasible set of power consumptions, respectively. We define \\mathbf{I}_n \\triangleq \\{\\omega_n, \\mathbf{M}_n, \\mathbf{m}_n, E_n\\} \\tag{15} and \\hat{\\mathbf{I}}_n \\triangleq \\{\\hat{\\omega}_n, \\hat{\\mathbf{M}}_n, \\hat{\\mathbf{m}}_n, \\hat{E}_n\\}. \\tag{16}"},{"evidence_id":"v141-b-g02-e017","location":{"location_id":"src-0fb1d9d41e-p06-c1r3__v141-a-M01-clearing","page":6,"printed_page":null,"section":"III-A VCG Mechanism","anchor_text":"sumption vectors as (21) wh and the payments are structured such that us (22) where is an arbitrary ","equation_id":"(21)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"For a given vector of declared demand information \\(\\hat{\\mathbf I}\\), the VCG mechanism chooses the energy consumption allocation \\(\\mathbf x(\\hat{\\mathbf I})\\) as an optimal solution to problem (10) and calculates optimal energy consumption vectors as\n\\[ \\mathbf x(\\hat{\\mathbf I})=\\underset{\\mathbf x_n\\in\\hat{\\mathcal X}_n,\\ n\\in\\mathcal N}{\\arg\\max}\\left\\{\\sum_{n\\in\\mathcal N}\\hat U_n\\left(\\sum_{k\\in\\mathcal K}x_n^k\\right)-\\sum_{k\\in\\mathcal K}C_k\\left(\\sum_{n\\in\\mathcal N}x_n^k\\right)\\right\\}. \\tag{21} \\]"},{"evidence_id":"v141-b-g02-e021","location":{"location_id":"src-0fb1d9d41e-p06-c2r2__v141-a-M01-pricing","page":6,"printed_page":null,"section":"III-A VCG Mechanism","anchor_text":"this strategy results in an efﬁcient allocation. , The proof of Proposition 3 is given in Appendix A","equation_id":"(23)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"Here, we will use a popular choice for this function which is referred to as Clarke tax [37],\n\\[ h_n(\\hat{\\mathbf I}_{-n})=\\sum_{m\\in\\mathcal N_{-n}}\\hat U_m\\left(\\sum_{k\\in\\mathcal K}x_m^k(\\hat{\\mathbf I}_{-n})\\right)-\\sum_{k\\in\\mathcal K}C_k\\left(\\sum_{m\\in\\mathcal N_{-n}}x_m^k(\\hat{\\mathbf I}_{-n})\\right), \\tag{23} \\]\nwhere \\(\\mathbf x(\\hat{\\mathbf I}_{-n})\\) is the VCG allocation choice in (21), but when user \\(n\\) is excluded from the system."},{"evidence_id":"v141-b-g02-e022","location":{"location_id":"src-0fb1d9d41e-p06-c2r4__v141-a-M01-pricing","page":6,"printed_page":null,"section":"III-A VCG Mechanism","anchor_text":"ns to c- (24) a on he The payment of user is the difference in the social welfare y- of the other us","equation_id":"(24)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"Thus, the payment of user \\(n\\) is\n\\[ t_n(\\hat{\\mathbf I})=-\\left(\\sum_{m\\in\\mathcal N_{-n}}\\hat U_m\\left(\\sum_{k\\in\\mathcal K}x_m^k(\\hat{\\mathbf I})\\right)-\\sum_{k\\in\\mathcal K}C_k\\left(\\sum_{m\\in\\mathcal N}x_m^k(\\hat{\\mathbf I})\\right)\\right)+\\left(\\sum_{m\\in\\mathcal N_{-n}}\\hat U_m\\left(\\sum_{k\\in\\mathcal K}x_m^k(\\hat{\\mathbf I}_{-n})\\right)-\\sum_{k\\in\\mathcal K}C_k\\left(\\sum_{m\\in\\mathcal N_{-n}}x_m^k(\\hat{\\mathbf I}_{-n})\\right)\\right). \\tag{24} \\]\nThe payment of user \\(n\\) is the difference in the social welfare of the other users with and without the presence of user \\(n\\)."},{"evidence_id":"v141-b-g02-e023","location":{"location_id":"src-0fb1d9d41e-p07-c1r1__v141-a-M01-settlement","page":7,"printed_page":null,"section":"III-B VCG Mechanism and Nonnegative Transfer","anchor_text":"1176 formulation considered in this paper, since users are only elec- tricity consumers, this case d","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"condition"},"source_text":"In general, if users can serve as a source of electricity at some time instances during the day, e.g., because they have local generation capability or they can transfer the power stored in their local batteries back to the grid, then such users may receive payments from the grid. Such payments can also be interpreted as negative payments made by the users. However, in the problem formulation considered in this paper, since users are only electricity consumers, this case does not arise, and the users’ payments to the grid are always nonnegative. We will refer to this property as nonnegative transfer. In the following theorem, we show that for our problem formulation the nonnegative transfer property holds.\nTheorem 2: Suppose Properties 1–4 and Assumptions 1–3 hold. Then, the VCG mechanism in (21) and (24) has the property of nonnegative transfer."},{"evidence_id":"v141-b-g02-e024","location":{"location_id":"src-0fb1d9d41e-p07-c1r2__v141-a-M01-pricing","page":7,"printed_page":null,"section":"III-C VCG Mechanism and Market Clearing Price","anchor_text":"The proof of Theorem 2 is given in Appendix B. C. VCG Mechanism and Market Clearing Price The follow","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"definition"},"source_text":"The following theorem shows that the electricity payment of each user in the proposed VCG mechanism is less than its payment in a system which has price taking users and uses marginal cost pricing, i.e., the \\(\\boldsymbol\\lambda\\) term in Proposition 1.\nTheorem 3: Suppose Properties 1–4 and Assumptions 1–3 hold. For the VCG mechanism in (21) and (24), the payment of each user is \\(t_n\\le\\sum_{k\\in\\mathcal K}\\lambda_k^*x_n^k(\\mathbf I)\\), where \\(\\boldsymbol\\lambda^*=(\\lambda_1^*,\\ldots,\\lambda_K^*)\\) is the vector of market clearing prices for problem (10)."},{"evidence_id":"v141-b-g01-E07","location":{"location_id":"src-0fb1d9d41e-p02-c2r2__v141-a-M01-validation","page":2,"printed_page":"1171","section":"I. INTRODUCTION","anchor_text":"set We propose a VCG mechanism for DSM programs to en he courage efﬁcient energy consumption among u","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"Then, for our model, we show the property of nonnegative transfer which means that the users always make nonnegative payments."},{"evidence_id":"v141-b-g02-e013","location":{"location_id":"src-0fb1d9d41e-p05-c2r4__v141-a-M01-bidding","page":5,"printed_page":null,"section":"III-A VCG Mechanism","anchor_text":"gy A. VCG Mechanism me In the VCG class of mechanisms, each user is asked to specify ot. its feasibl","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"In the VCG class of mechanisms, each user is asked to specify its feasible set of power consumption and its utility function, which in case of the utility functions in (7) reduces to revealing a utility parameter \\(\\omega_n\\). For each user \\(n\\), we use \\(U_n(\\sum_{k\\in\\mathcal K}x_n^k,\\omega_n)\\) and \\(\\hat U_n(\\sum_{k\\in\\mathcal K}x_n^k,\\hat\\omega_n)\\) to denote the true and declared utility function and \\(\\mathcal X_n\\) and \\(\\hat{\\mathcal X}_n\\) to denote the true and declared feasible set of power consumptions, respectively. We define\n\\[ \\mathbf I_n\\triangleq\\{\\omega_n,\\mathbf M_n,\\mathbf m_n,E_n\\} \\tag{15} \\]\nand\n\\[ \\hat{\\mathbf I}_n\\triangleq\\{\\hat\\omega_n,\\hat{\\mathbf M}_n,\\hat{\\mathbf m}_n,\\hat E_n\\}. \\tag{16} \\]"},{"evidence_id":"v141-b-g02-e014","location":{"location_id":"src-0fb1d9d41e-p06-c1r1__v141-a-M01-bidding","page":6,"printed_page":null,"section":"III-A VCG Mechanism","anchor_text":"SAMADI et al.: ADVANCED DEMAND SIDE MANAGEMENT FOR THE FUTURE SMART to denote the true and declared ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"to denote the true and declared demand parameters, respectively, where \\(\\hat{\\boldsymbol\\omega}\\), \\(\\hat{\\mathbf M}\\), \\(\\hat{\\mathbf m}\\), and \\(\\hat{\\mathbf E}\\) are the declared values for \\(\\boldsymbol\\omega\\), \\(\\mathbf M\\), \\(\\mathbf m\\), and \\(\\mathbf E\\), respectively. For notational simplicity, we also define\n\\[ \\mathbf I\\triangleq\\{\\boldsymbol\\omega,\\mathbf M,\\mathbf m,\\mathbf E\\} \\tag{17} \\]\nand\n\\[ \\hat{\\mathbf I}\\triangleq\\{\\hat{\\boldsymbol\\omega},\\hat{\\mathbf M},\\hat{\\mathbf m},\\hat{\\mathbf E}\\}, \\tag{18} \\]\nwhere \\(\\hat{\\boldsymbol\\omega}\\), \\(\\hat{\\mathbf M}\\), \\(\\hat{\\mathbf m}\\), and \\(\\hat{\\mathbf E}\\) are the declared values for vectors \\(\\boldsymbol\\omega\\), \\(\\mathbf M\\), \\(\\mathbf m\\), and \\(\\mathbf E\\), respectively."},{"evidence_id":"v141-b-g02-e015","location":{"location_id":"src-0fb1d9d41e-p06-c1r2__v141-a-M01-bidding","page":6,"printed_page":null,"section":"III-A VCG Mechanism","anchor_text":"th where , , , and are the declared values for vectors , , , and , respectively. If user has a consu","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"If user \\(n\\) has a consumption vector \\(\\mathbf x_n\\), but has to pay \\(t_n\\), then the payoff function of user \\(n\\) is\n\\[ U_n\\left(\\sum_{k\\in\\mathcal K}x_n^k\\right)-t_n. \\tag{19} \\]"},{"evidence_id":"v141-b-g02-e016","location":{"location_id":"src-0fb1d9d41e-p06-c1r2__v141-a-M01-clearing","page":6,"printed_page":null,"section":"III-A VCG Mechanism","anchor_text":"th where , , , and are the declared values for vectors , , , and , respectively. If user has a consu","equation_id":"(20)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"On the other hand, the social objective is in the form of\n\\[ U_n\\left(\\sum_{k\\in\\mathcal K}x_n^k\\right)+\\sum_{m\\in\\mathcal N_{-n}}U_m\\left(\\sum_{k\\in\\mathcal K}x_m^k\\right)-\\sum_{k\\in\\mathcal K}C_k\\left(\\sum_{m\\in\\mathcal N}x_m^k\\right), \\tag{20} \\]\nwhere \\(\\mathcal N_{-n}\\) is the set of all users except user \\(n\\)."},{"evidence_id":"v141-b-g02-e018","location":{"location_id":"src-0fb1d9d41e-p06-c1r3__v141-a-M01-pricing","page":6,"printed_page":null,"section":"III-A VCG Mechanism","anchor_text":"sumption vectors as (21) wh and the payments are structured such that us (22) where is an arbitrary ","equation_id":"(22)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"and the payments are structured such that\n\\[ t_n(\\hat{\\mathbf I})=-\\left(\\sum_{m\\in\\mathcal N_{-n}}\\hat U_m\\left(\\sum_{k\\in\\mathcal K}x_m^k\\right)-\\sum_{k\\in\\mathcal K}C_k\\left(\\sum_{m\\in\\mathcal N}x_m^k\\right)\\right)+h_n(\\hat{\\mathbf I}_{-n}), \\tag{22} \\]\nwhere \\(h_n\\) is an arbitrary function of \\(\\hat{\\mathbf I}_{-n}\\), i.e., the declared demand information of the users with user \\(n\\) excluded from the system. The true demand information of the users other than \\(n\\) is denoted by \\(\\mathbf I_{-n}\\). The definition of the payments in (22) aligns user objectives with the social planner’s objective."},{"evidence_id":"v141-b-g02-e030","location":{"location_id":"src-0fb1d9d41e-p09-c2r3__v141-a-M01-validation","page":9,"printed_page":null,"section":"Appendix B. Proof of Theorem 2","anchor_text":"ost er- cy, hat he mp- CG ad. our by where is the optimal solution for the social objective ng when ","equation_id":"(25)","figure_id":null,"table_id":null,"image_ref":"pages/page-09.png","occurrence_role":"formula"},"source_text":"where \\(\\mathbf x(\\mathbf I_{-n})\\) is the optimal solution for the social objective when user \\(n\\) is excluded from the system. So, we have\n\\[ \\sum_{m\\in\\mathcal N_{-n}}U_m\\left(\\sum_{k\\in\\mathcal K}x_m^k(\\mathbf I_{-n})\\right)-\\sum_{k\\in\\mathcal K}C_k\\left(\\sum_{m\\in\\mathcal N}x_m^k(\\mathbf I_{-n})\\right)\\ge\\sum_{m\\in\\mathcal N_{-n}}U_m\\left(\\sum_{k\\in\\mathcal K}x_m^k(\\mathbf I)\\right)-\\sum_{k\\in\\mathcal K}C_k\\left(\\sum_{m\\in\\mathcal N}x_m^k(\\mathbf I)\\right). \\tag{25} \\]\nFurthermore, from Assumption 1, \\(C_k(\\cdot)\\) is an increasing function. Therefore, we have\n\\[ \\sum_{m\\in\\mathcal N_{-n}}U_m\\left(\\sum_{k\\in\\mathcal K}x_m^k(\\mathbf I_{-n})\\right)-\\sum_{k\\in\\mathcal K}C_k\\left(\\sum_{m\\in\\mathcal N_{-n}}x_m^k(\\mathbf I_{-n})\\right)\\ge\\sum_{m\\in\\mathcal N_{-n}}U_m\\left(\\sum_{k\\in\\mathcal K}x_m^k(\\mathbf I)\\right)-\\sum_{k\\in\\mathcal K}C_k\\left(\\sum_{m\\in\\mathcal N}x_m^k(\\mathbf I)\\right). \\tag{26} \\]\nand thus (24) is nonnegative."},{"evidence_id":"v141-b-g03-e01-vcg-declaration","location":{"location_id":"src-0fb1d9d41e-p08-c1r2__v141-a-M01-bidding","page":8,"printed_page":null,"section":"IV-C Communication Requirements of the VCG System","anchor_text":"Fig. 4. Payoff of the energy provider for the proposed VCG system, the system with price anticipatin","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-08.png","occurrence_role":"definition"},"source_text":"In the VCG system, each user is asked to declare its parameter \\omega and its feasible set of power consumption to the energy provider, and in return, the energy provider determines the payment and the allocated power of each user."},{"evidence_id":"v141-b-g03-e12-eq27","location":{"location_id":"src-0fb1d9d41e-p10-c1r2__v141-a-M01-pricing","page":10,"printed_page":null,"section":"Appendix C. Proof of Theorem 3","anchor_text":"Since is the optimal solution for the social objective problem, the optimality conditions of (21) im","equation_id":"(27)","figure_id":null,"table_id":null,"image_ref":"pages/page-10.png","occurrence_role":"formula"},"source_text":"Since x(\\mathbf{I}) is the optimal solution for the social objective problem, the optimality conditions of (21) imply that \\lambda_k^* = p_k\\left(\\sum_{n\\in\\mathcal{N}} x_n^k(\\mathbf{I})\\right), U_n'\\left(\\sum_{k\\in\\mathcal{K}} x_n^k(\\mathbf{I})\\right) = \\lambda_k^*, \\text{ if } x_n^k(\\mathbf{I}) > m_n^k \\text{ and } \\sum_{k\\in\\mathcal{K}} x_n^k(\\mathbf{I}) > E_n, U_n'\\left(\\sum_{k\\in\\mathcal{K}} x_n^k(\\mathbf{I})\\right) \\le \\lambda_k^*, \\text{ if } x_n^k(\\mathbf{I}) = m_n^k \\text{ or } \\sum_{k\\in\\mathcal{K}} x_n^k(\\mathbf{I}) = E_n. \\tag{27} where p_k(\\cdot) has been introduced in (8), and \\lambda_k^* is the market clearing price for the problem (10)."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-clearing","v141-a-M01-participation","v141-a-M01-pricing","v141-a-M01-settlement","v141-a-M01-validation","v141-a-M02-pricing"],"extras":{"decision_anchor":"settlement.payment","graph_fact_supports":[[{"evidence_id":"v141-b-g01-E02","quote":"Our design requires that each user provides some information about its energy demand. In return, the energy provider will determine each user’s electricity bill payment."},{"evidence_id":"v141-b-g01-E29","quote":"In the VCG class of mechanisms, each user is asked to specify its feasible set of power consumption and its utility function"}],[{"evidence_id":"v141-b-g02-e022","quote":"The payment of user \\(n\\) is the difference in the social welfare of the other users with and without the presence of user \\(n\\)."},{"evidence_id":"v141-b-g02-e021","quote":"where \\(\\mathbf x(\\hat{\\mathbf I}_{-n})\\) is the VCG allocation choice in (21), but when user \\(n\\) is excluded from the system."},{"evidence_id":"v141-b-g02-e017","quote":"For a given vector of declared demand information \\(\\hat{\\mathbf I}\\), the VCG mechanism chooses the energy consumption allocation \\(\\mathbf x(\\hat{\\mathbf I})\\) as an optimal solution to problem (10)"},{"evidence_id":"v141-b-g01-E19","quote":"The objective function in problem (10) is the sum of all utility functions minus the total energy cost in the system."}],[{"evidence_id":"v141-b-g02-e023","quote":"However, in the problem formulation considered in this paper, since users are only electricity consumers, this case does not arise, and the users’ payments to the grid are always nonnegative."},{"evidence_id":"v141-b-g02-e023","quote":"Theorem 2: Suppose Properties 1–4 and Assumptions 1–3 hold. Then, the VCG mechanism in (21) and (24) has the property of nonnegative transfer."}],[{"evidence_id":"v141-b-g02-e024","quote":"Theorem 3: Suppose Properties 1–4 and Assumptions 1–3 hold. For the VCG mechanism in (21) and (24), the payment of each user is \\(t_n\\le\\sum_{k\\in\\mathcal K}\\lambda_k^*x_n^k(\\mathbf I)\\), where \\(\\boldsymbol\\lambda^*=(\\lambda_1^*,\\ldots,\\lambda_K^*)\\) is the vector of market clearing prices for problem (10)."}]],"C2_formalization":{"graph_sha256":"9b909a49df1912f24dc8b6ba108d4d8e36420d0c817ed25e7fb0cf8127b1bd1f","applicability":"formalized","reason":"The settlement rule is formalized from the source's Clarke-tax equation (23) and payment equation (24) in C002, the nonnegative-transfer property as t_n >= 0 in C003, and Theorem 3's payment bound t_n \u003c= sum_k lambda_k^* x_n^k(I) in C004. C001 remains procedural because the source states an information-flow requirement rather than an equation. The frozen graph can represent these formulas through bidding.demand, clearing.social_welfare, settlement.payment, and edges E001/E002; no graph revision is requested. B evidence used here is unreviewed candidate support under the experiment policy, not independently verified source review.","bindings":[{"object_id":"v141-c-R003-C001","node_ids":["bidding.demand","settlement.payment"],"edge_ids":["v141-c-R003-E001"],"rationale":"C001 describes the declaration-to-bill link represented by E001; it remains procedural because the source states an information-flow requirement rather than an equation."},{"object_id":"v141-c-R003-C002","node_ids":["clearing.social_welfare","settlement.payment"],"edge_ids":["v141-c-R003-E002"],"rationale":"The Clarke-tax payment (24) uses full-system and user-excluded social-welfare allocations from clearing.social_welfare to determine settlement.payment."},{"object_id":"v141-c-R003-C003","node_ids":["settlement.payment"],"edge_ids":["v141-c-R003-E002"],"rationale":"Nonnegative transfer is a property of the VCG payment produced by (21) and (24), whose clearing-to-payment link is E002."},{"object_id":"v141-c-R003-C004","node_ids":["bidding.demand","clearing.social_welfare","settlement.payment"],"edge_ids":["v141-c-R003-E001","v141-c-R003-E002"],"rationale":"Theorem 3 bounds the settlement payment by the market-clearing-price value of the VCG allocation at true demand information, linking bidding declarations, clearing prices, and payment."},{"object_id":"v141-c-R003-x-t-n","node_ids":["settlement.payment"],"edge_ids":["v141-c-R003-E001","v141-c-R003-E002"],"rationale":"t_n is the VCG electricity bill at settlement.payment; it is determined from declared demand information (E001) and clearing outcomes (E002)."},{"object_id":"v141-c-R003-x-xnk","node_ids":["clearing.social_welfare","settlement.payment"],"edge_ids":["v141-c-R003-E002"],"rationale":"x_n^k is the VCG-allocated consumption from clearing.social_welfare that enters the payment formula at settlement.payment via E002."},{"object_id":"v141-c-R003-theta-Ihat","node_ids":["bidding.demand","settlement.payment"],"edge_ids":["v141-c-R003-E001"],"rationale":"Declared demand information is submitted in bidding.demand and is an input to the payment formula at settlement.payment (E001)."},{"object_id":"v141-c-R003-theta-Ihat-minus-n","node_ids":["bidding.demand","settlement.payment"],"edge_ids":["v141-c-R003-E001"],"rationale":"Declared demand information excluding user n is the Clarke-tax argument in the payment formula and is part of the bidding declarations linked to payment by E001."},{"object_id":"v141-c-R003-theta-I","node_ids":["bidding.demand","settlement.payment"],"edge_ids":["v141-c-R003-E001"],"rationale":"True demand information is used to evaluate Theorem 3's payment bound; it is the truthful demand-information counterpart of the bidding declarations linked to settlement.payment by E001."},{"object_id":"v141-c-R003-theta-lambda-star","node_ids":["clearing.social_welfare","settlement.payment"],"edge_ids":["v141-c-R003-E002"],"rationale":"lambda_k^* is the market-clearing price for problem (10) from clearing.social_welfare and appears in the payment bound at settlement.payment via E002."}],"revision_requests":[]}},"quarantined_references":[]}});
